import{n as e}from"./index-CzwAhvGh.js";const t={title:`Zafu Security`,heading:`Security`,lede:`Zafu is built around a hot/cold key split: the wallet holds viewing keys and builds transactions; spending keys stay on an air-gapped signer. All zero-knowledge proving happens client-side.`,sections:[{id:`cold-signing`,title:`Cold Signing`,lede:`Zafu pairs with Zigner over a camera-only channel. The wallet constructs an unsigned transaction, streams it as animated QR codes, and the signer returns signatures the same way. No USB, Bluetooth, or network path exists between the two devices.`,blocks:[{kind:`specs`,entries:[{title:`Transaction format`,value:`PCZT v2`,description:`Partially Created Zcash Transactions carry the unsigned transaction, proofs, and signatures between devices. The signer decodes the full effects of what it signs.`},{title:`QR transport`,value:`RaptorQ + UR`,description:`Fountain coding lets the receiver reconstruct the payload from any sufficient subset of frames — no frame ordering, no retransmission back-channel.`},{title:`Key separation`,value:`viewing / spending`,description:`Zafu holds viewing keys only. Compromise of the online wallet exposes transaction-history visibility, never spend authority.`}]}]},{id:`frost`,title:`FROST Threshold Signing`,lede:`With FROST, a single spending key never needs to exist on any one device. Key generation is distributed and signing requires a threshold of participants.`,blocks:[{kind:`specs`,entries:[{title:`Ciphersuites`,value:`RedPallas / decaf377`,description:`RedPallas for Zcash Orchard spend authorization; decaf377 for Penumbra.`},{title:`Key generation`,value:`3-round DKG`,description:`Dealerless distributed key generation. The full spending key is never assembled on any device at any point in its lifecycle.`},{title:`Nonce reuse detection`,value:`commitment fingerprints`,description:`Signing nonce commitments are fingerprinted and checked across sessions; a repeated nonce aborts the session before any signature share is produced.`}]}]},{id:`key-storage`,title:`Key Storage & Client-Side Proving`,blocks:[{kind:`specs`,entries:[{title:`Proving`,value:`in-browser`,description:`Zero-knowledge proofs for shielded transactions are generated locally. No transaction plaintext, key material, or witness data leaves the device.`},{title:`Server trust`,value:`minimized`,description:`Remote infrastructure only ever sees fully-formed shielded transactions for broadcast. Query-side trust in Zidecar/lightwalletd is actively minimized — see below.`},{title:`ZID identity keys`,value:`ed25519`,description:`Per-site and per-contact key derivation prevents cross-context linkability. Payloads are encrypted with AES-256-GCM.`}]}]},{id:`backend-trust`,title:`Backend Trust Minimization`,lede:`The query backend (Zidecar / lightwalletd) is treated as an adversary for metadata. Opt-in verification and decoy traffic shrink what a provider can learn or lie about — or run your own.`,blocks:[{kind:`specs`,entries:[{title:`Decoy fetching`,value:`bucket + decoy`,description:`Memo and note fetches mix real buckets with random decoy buckets (2× in private mode, 5× in paranoid), shuffled together — the server cannot distinguish which requests are yours.`},{title:`Ligerito proofs`,value:`opt-in`,description:`Succinct proofs over server responses: Merkle paths for nullifiers and commitments are verified locally, bound to the batch root and the request set.`},{title:`NOMT verification`,value:`opt-in`,description:`Local state verification against NOMT (Nearly Optimal Merkle Trie) proofs, surfaced live in the sync status.`},{title:`Cross-endpoint verify`,value:`chain tips`,description:`Chain tips are compared across independent endpoints, catching a server that reports a state no one else agrees with.`},{title:`Honest limits`,value:`partial, not trustless`,description:`The Ligerito header proof has no constraint system yet: the roots it proves are values the prover chose and absorbed into its own transcript, so nothing ties them to what consensus committed. That part is ours to fix. Block and action omission is separate and harder — a server can serve a valid header chain and still withhold data, and no amount of client-side verification detects it. Cross-endpoint comparison is wired as an advisory mitigation, not a proof. Hence partial.`},{title:`Self-hosting`,value:`Zidecar / pd`,description:`All RPC endpoints are configurable; run your own query backend to remove provider metadata exposure entirely.`}]}]}]},n={title:`Zafu Specs`,heading:`Specifications`,lede:`Protocol support, cryptography, and identity system details.`,sections:[{id:`architecture`,title:`Architecture`,blocks:[{kind:`specs`,entries:[{title:`Lineage`,value:`Prax fork`,description:`Zafu is forked from Prax Wallet (Penumbra Labs), extending it with Zcash support, cold signing, FROST, and ZID.`},{title:`Local-first`,value:`on-device`,description:`All actions — encryption, proof generation, and balance sync — are handled by your local device.`},{title:`Custody`,value:`non-custodial`,description:`You are the only one who holds your keys; in the recommended setup, spending keys live on an air-gapped Zigner.`}]}]},{id:`zcash`,title:`Zcash Protocol`,blocks:[{kind:`specs`,entries:[{title:`Pools`,value:`Ironwood / Orchard / Transparent`,description:`Ironwood is the active shielded pool. Orchard is legacy — migrate-only through the NU6.3 one-way turnstile. Transparent funds can be shielded on receipt.`},{title:`Spend authorization`,value:`RedPallas`,description:`Signature scheme for Orchard spend authorization.`},{title:`Cold signing format`,value:`PCZT v2`,description:`Partially Created Zcash Transactions carry unsigned transaction data between wallet and signer.`},{title:`Proving`,value:`client-side`,description:`Proofs for shielded actions are generated in the browser; no external proving service is used.`}]}]},{id:`penumbra`,title:`Penumbra`,blocks:[{kind:`specs`,entries:[{title:`Signatures`,value:`decaf377`,description:`Penumbra's native signature scheme over the decaf377 group.`},{title:`Swaps`,value:`DEX`,description:`Shielded batch swaps on the Penumbra DEX.`},{title:`Staking`,value:`delegate / undelegate`,description:`Delegation and undelegation via delegation tokens.`},{title:`Governance`,value:`voting`,description:`On-chain governance voting.`},{title:`IBC`,value:`transfers`,description:`Deposit and withdraw assets to and from IBC-connected chains.`}]}]},{id:`frost`,title:`FROST Multisig`,blocks:[{kind:`specs`,entries:[{title:`Ciphersuites`,value:`RedPallas / decaf377`,description:`RedPallas for Zcash, decaf377 for Penumbra.`},{title:`Key generation`,value:`3-round DKG`,description:`Dealerless; participants exchange rounds over the QR channel and each holds only a key share.`},{title:`Signing`,value:`2-round, t-of-n`,description:`Any t of n participants produce a signature; round one exchanges nonce commitments, round two signature shares.`},{title:`Nonce safety`,value:`reuse detection`,description:`Commitment fingerprints are tracked across signing sessions; reuse aborts before any share is emitted.`}]}]},{id:`zid`,title:`ZID Identity`,lede:`Off-chain identity. Build your own social graph — no KYC, no registry, no linkable global identifier.`,blocks:[{kind:`specs`,entries:[{title:`Key type`,value:`ed25519`,description:`Identity keys for authentication and messaging.`},{title:`Derivation`,value:`per-site / per-contact`,description:`Independent keys per context; no shared identifier links activity across sites or contacts.`},{title:`Social graph`,value:`self-sovereign`,description:`Contacts are pairwise keys you exchange directly. Your graph lives with you, encrypted — not on a server, not on a chain.`},{title:`Encryption`,value:`AES-256-GCM`,description:`Authenticated encryption for ZID payloads.`}]}]}]},r={title:`Zafu Docs`,heading:`Documentation`,lede:`Zafu runs in the browser with all key operations and proving performed locally. This guide covers wallet setup, transaction types, and the cold-signing and FROST workflows.`,sections:[{id:`install`,title:`Installing the Latest Beta`,lede:`Zafu is in beta: the Chrome Web Store build lags while reviews land, so GitHub always has the newest release. Some apps (like zk.poker) need the latest beta.`,blocks:[{kind:`steps`,steps:[{title:`Download`,body:`Grab zafu-beta-*.zip (or .crx) from the latest GitHub release and unzip it.`,link:{href:`https://github.com/rotkonetworks/zafu/releases/latest`,text:`download latest zafu-beta (.zip / .crx) →`}},{title:`Enable developer mode`,body:`Open chrome://extensions and toggle Developer mode on (top right).`},{title:`Load unpacked`,body:`Click Load unpacked and pick the unzipped folder.`},{title:`Reload`,body:`Reload any open dapp pages so they see the new wallet version. To update later, download the new zip and Load unpacked again.`}]}]},{id:`setup`,title:`Wallet Setup`,blocks:[{kind:`steps`,steps:[{title:`Open Zafu`,body:`Zafu is a web wallet; no installation is required. All cryptographic operations, including proof generation, run client-side.`},{title:`Create or restore`,body:`Generate a new seed phrase, or restore from an existing one. For restores, provide the wallet birthday (block height) to bound the initial scan.`},{title:`Choose a security posture`,body:`Hot wallet: keys stay in the browser. Recommended: watch-only mode — import viewing keys from Zigner so Zafu can scan and build transactions while spending keys remain air-gapped.`},{title:`Sync`,body:`The wallet trial-decrypts compact blocks with your viewing keys to discover notes. Scanning happens locally; the server learns nothing about which notes are yours.`}]}]},{id:`zcash-transactions`,title:`Zcash Transactions`,blocks:[{kind:`specs`,entries:[{title:`Shielded send`,value:`Ironwood → Ironwood`,description:`Default Zcash transaction type. Amounts, sender, and receiver are hidden.`},{title:`Shielding`,value:`Transparent → Ironwood`,description:`Moves transparent funds into the active shielded pool.`},{title:`Deshielding`,value:`Ironwood → Transparent`,description:`For paying transparent-only addresses. Reveals the amount and destination.`},{title:`Migration`,value:`Orchard → Ironwood`,description:`One-way turnstile. NU6.3 makes Orchard migrate-only; legacy funds stay safe until you move them through.`}]}]},{id:`penumbra-transactions`,title:`Penumbra Transactions`,blocks:[{kind:`specs`,entries:[{title:`Swap`,value:`DEX`,description:`Shielded batch swap on the Penumbra DEX.`},{title:`Staking`,value:`delegate / undelegate`,description:`Stake to and unstake from Penumbra validators.`},{title:`Voting`,value:`governance`,description:`On-chain governance votes.`},{title:`IBC transfer`,value:`deposit / withdraw`,description:`Move assets between Penumbra and IBC-connected chains.`}]}]},{id:`cold-signing-flow`,title:`Signing with Zigner`,lede:`In watch-only mode, every spend is a two-device round trip over QR codes.`,blocks:[{kind:`steps`,steps:[{title:`Build`,body:`Zafu constructs the unsigned transaction (PCZT v2 for Zcash) and generates proofs locally.`},{title:`Display`,body:`The payload is UR-encoded, fountain-coded with RaptorQ, and shown as an animated QR sequence.`},{title:`Sign`,body:`Zigner scans the sequence, displays the transaction for review on its own screen, and signs with the spending key after confirmation.`},{title:`Return & broadcast`,body:`Zigner displays the signatures as QR codes; Zafu scans them, finalizes the transaction, and broadcasts it.`}]}]},{id:`frost-setup`,title:`FROST Multisig Setup`,blocks:[{kind:`steps`,steps:[{title:`Pick parameters`,body:`Choose threshold t and participant count n, and the ciphersuite: RedPallas for Zcash, decaf377 for Penumbra.`},{title:`Run DKG`,body:`All n participants complete the 3-round distributed key generation, exchanging rounds via QR. Each device ends with a key share; the full key never exists anywhere.`},{title:`Verify`,body:`Confirm every participant derived the same group verification key before sending funds to the multisig address.`},{title:`Sign`,body:`Any t participants run the 2-round signing protocol over the same QR channel. Nonce commitments are fingerprinted and checked to prevent reuse.`}]}]},{id:`support`,title:`Support & Community`,lede:`Zafu bugs and feature requests belong on our issue tracker — that is the channel we watch — and we post progress in our Zcash forum development thread. The Zcash and Penumbra Discords are upstream protocol communities: the right place for questions about the chains themselves, not about the wallet.`,blocks:[{kind:`links`,links:e}]}]},i={title:`Zafu Roadmap`,heading:`Roadmap`,lede:`Where Zafu is headed. Priorities can shift with network upgrades; the latest state is always the GitHub milestones.`,sections:[{id:`high-priority`,title:`High Priority`,blocks:[{kind:`specs`,entries:[{title:`Post-quantum encryption`,value:`PQ migration`,description:`Move wallet-layer encryption (vault, ZID payloads, QR channel) to post-quantum schemes so captured ciphertext today cannot be harvested and decrypted later.`},{title:`OTA updates over QR`,value:`no reinstalls`,description:`Ship wallet logic updates over the animated QR channel so network upgrades like NU7 do not force an extension reinstall — the store review cycle stops gating consensus changes.`}]}]},{id:`next`,title:`Next`,blocks:[{kind:`specs`,entries:[{title:`Constrained header proofs`,value:`prover-chosen → committed`,description:`Give the Ligerito header proof a constraint system, so the roots it proves are the ones block headers already commit to rather than values the prover picked. Per-pool pinned roots are the precondition: a proof cannot bind to a root the server cannot name at a given height.`},{title:`Block omission`,value:`needs consensus-layer DA`,description:`A server can serve a valid header chain and still withhold blocks or actions. Detecting that needs data-availability commitments from block producers — a network change, not a wallet one. Listed here because it bounds how trustless a light client can honestly claim to be.`},{title:`Ledger shielded signing`,value:`flag-off today`,description:`Shielded (Ironwood/Orchard) signing on Ledger hardware — not just transparent. Ships disabled until Ledger's app-zcash recognises the current branch id and frame shape; re-enabled once upstream releases land.`},{title:`PIR voting`,value:`Zcash + Penumbra`,description:`Governance voting over private information retrieval on both chains: the query backend cannot see which proposals you fetch or correlate reads with votes.`}]}]}]};export{n as i,i as n,t as r,r as t};